def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The three adjacent nonzero cells in the first row define the line colors.
    start = next(c for c in range(w - 2)
                 if all(grid[0][c + k] != 0 for k in range(3)))
    colors = grid[0][start:start + 3]

    for k, color in enumerate(colors):
        col = start + k
        markers = [(r, c) for r in range(h) for c in range(w)
                   if grid[r][c] == color and r != 0]
        if not markers:
            for r in range(h):
                out[r][col] = color
            continue

        # Each matching marker is joined to the top pattern by a vertical ray,
        # then extended horizontally from the marker out to the grid edge.
        for r, c in markers:
            for y in range(min(r, 0), max(r, 0) + 1):
                out[y][col] = color
            if c < col:
                for x in range(c, col + 1):
                    out[r][x] = color
            elif c > col:
                for x in range(col, c + 1):
                    out[r][x] = color
                for x in range(c, w):
                    out[r][x] = color
    return out
